function StepKeystore{if(-not $script:Ctx.Paths){throw 'Run SigningRepository first.'};$p=$script:Ctx.Paths;Section 'Android upload keystore';if(Test-Path -LiteralPath $p.KeystorePath -PathType Leaf){$a=Read-Host 'Existing keystore found. Reuse? [Y]es / [N]o / [C]ancel';if($a -match '^[Cc]$'){throw 'Cancelled.'};if($a -notmatch '^[Yy]$'){throw 'Existing keystore is never overwritten automatically.'};$alias=Ask 'Existing keystore alias' {param($v)if($v -notmatch '^[A-Za-z0-9._-]{1,64}$'){throw 'Invalid alias.'};return $true};$store=Ask 'Existing keystore password' {param($v)return -not [string]::IsNullOrWhiteSpace($v)} -Secret;$key=Ask 'Existing key password' {param($v)return -not [string]::IsNullOrWhiteSpace($v)} -Secret;$subject='Existing certificate'}else{$alias=Ask 'Keystore alias' {param($v)if($v -notmatch '^[A-Za-z0-9._-]{3,64}$'){throw 'Alias must be 3-64 valid characters.'};return $true};$store=Ask 'Keystore password' {param($v)if(-not(StrongPassword $v)){throw 'Use 12+ characters with uppercase, lowercase, number and special character.'};return $true} -Secret;$key=Ask 'Key password' {param($v)if(-not(StrongPassword $v)){throw 'Use 12+ characters with uppercase, lowercase, number and special character.'};return $true} -Secret;$confirm=[Net.NetworkCredential]::new('',(Read-Host 'Confirm key password' -AsSecureString)).Password;if($confirm -cne $key){throw 'Key password confirmation did not match.'};$subject=Ask 'Certificate distinguished name' {param($v)return -not [string]::IsNullOrWhiteSpace($v)};$a=@('-genkeypair','-v','-keystore',$p.KeystorePath,'-alias',$alias,'-keyalg','RSA','-keysize','4096','-validity','10000','-storepass',$store,'-keypass',$key,'-dname',$subject);RunCommand keytool $a @(11,13);if(-not(Test-Path -LiteralPath $p.KeystorePath -PathType Leaf)){throw 'keytool did not create keystore.'}};$a=@('-list','-v','-keystore',$p.KeystorePath,'-alias',$alias,'-storepass',$store,'-keypass',$key);RunCommand keytool $a @(6,8);$script:Ctx.Signing=@{Alias=$alias;StorePassword=$store;KeyPassword=$key;KeystorePath=$p.KeystorePath;Subject=$subject};Log 'Keystore credentials validated.' Success}
